{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "While the acute phase of the disease was characterised early, there are still limited data on long- term outcomes.",
      "reason": "The introduction describes the current state of knowledge (acute phase characterised, ~15% hospitalised, ~5% critically ill) and the key uncertainty (limited data on long-term outcomes); text_3 adds that long COVID has 'an uncertain prevalence, for which there is currently no precise case definition'."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "While it is now apparent clinical sequelae (long COVID) may persist after acute COVID-19, their nature, frequency and aetiology are poorly characterised. This study aims to regularly synthesise evidence on long COVID characteristics, to help inform clinical management, rehabilitation strategies and interventional studies to improve long- term outcomes.",
      "reason": "The background explicitly explains the gap and the importance/need for the review, including informing clinical management, rehabilitation and interventional studies; text_8 further justifies the living review approach given rapidly emerging research."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "This is the first version of this LSR, which will be updated approximately every 6 months as new evidence emerges",
      "reason": "The manuscript states this is the first version of the living systematic review; no previous similar systematic review is identified or cited, so the conditional requirement to justify an update or replication does not apply."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of long COVID symptom prevalence/characterisation, not a review of intervention effects, so describing an intervention's mechanism of action does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review addresses prevalence and characterisation of long COVID symptoms, not a complex intervention or delivery context, so a logic model is not required."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "This study aims to regularly synthesise evidence on long COVID characteristics, to help inform clinical management, rehabilitation strategies and interventional studies to improve long-term outcomes.",
      "reason": "The objective is explicitly stated (to synthesise evidence on long COVID characteristics), supported by text_8 ('We conducted a 'living' systematic review to provide frequently updated evidence on the symptoms and complications of long COVID'), but it is not formulated using a recognised question-formulation framework (e.g., PICO, PCC), so the element is only partially met."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "This study aims to regularly synthesise evidence on long COVID characteristics",
      "reason": "This is a review characterising symptoms, complications and risk factors of long COVID, not a review of intervention effects, so planned comparisons in PICO form do not apply."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "Peer-­ reviewed studies were considered eligible if they included at least 100 people with laboratory confirmed and/or clinically diagnosed COVID-­ 19... we included studies that reported symptoms or outcomes assessed at 12 or more weeks post COVID-­ 19 onset.",
      "reason": "Population size, diagnosis, and follow-up requirements are specified, but eligible study designs and settings are not stated as eligibility criteria (study designs are only described retrospectively in text_18)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "There were no language restrictions. Reviews and opinion pieces were excluded. Studies were excluded if they included fewer than 100 participants... or the follow-­ up was unclear or less than 12 weeks post onset.",
      "reason": "Language (none), publication status (peer-reviewed only; reviews/opinion pieces and non-peer-reviewed preprints excluded per text_11 and text_14), and dissemination timeframe (search from 1 January 2020, text_10) are specified."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "We presented symptom proportions by different settings, as presented in the individual studies: hospitalised, non-­ hospitalised or a mix of both populations... Symptoms were broadly grouped into physiological clusters through discussion with clinicians... Additional subgroup analysis was conducted to explore the modification of the following factors on proportion of symptoms: hospitalisation, settings, continents and follow-­ up timing.",
      "reason": "Groups for the synthesis (symptom clusters, hospitalised vs non-hospitalised settings, subgroups by hospitalisation, settings, continents, follow-up timing) are specified and linked to the review objective of characterising long COVID symptoms."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Studies were excluded if they included fewer than 100 participants, to avoid small study effects, 18 or the follow-­ up was unclear or less than 12 weeks post onset.",
      "reason": "A rationale ('to avoid small study effects') is provided for the minimum sample size restriction."
    }
  ],
  "confidence": 88
}

